<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
const $q = useQuasar(), items = ref([]), current = ref(null), busy = ref(false), progress = ref(0), source = ref('file'), file = ref(null)
const form = reactive({ version: '', notes: '', url: '', filename: 'AitoNotify-Desktop.zip' })
const headers = () => ({ Authorization: `Bearer ${localStorage.getItem('aito_admin_token') || ''}` })
const size = bytes => `${(Number(bytes || 0) / 1024 / 1024).toFixed(1)} MB`
const failure = error => $q.notify({ type: 'negative', message: error.response?.data?.message || 'Não foi possível concluir a operação do pacote.' })
async function load() { try { const data = (await api.get('/admin/products/aitonotify/packages', { headers: headers() })).data.data; items.value = data.items; current.value = data.current } catch (error) { failure(error) } }
async function publish() {
  if (!form.version.trim() || (source.value === 'file' && !file.value)) return $q.notify({ type: 'warning', message: 'Informe a versão e escolha um arquivo ZIP/RAR.' })
  busy.value = true; progress.value = 0
  try {
    if (source.value === 'file') {
      const query = new URLSearchParams({ version: form.version.trim(), notes: form.notes, filename: file.value.name })
      await api.post('/admin/products/aitonotify/packages/upload?' + query, file.value, { headers: { ...headers(), 'Content-Type': 'application/octet-stream' }, timeout: 15 * 60000, onUploadProgress: event => { progress.value = event.total ? event.loaded / event.total : 0 } })
    } else await api.post('/admin/products/aitonotify/packages/import', { ...form }, { headers: headers(), timeout: 15 * 60000 })
    file.value = null; progress.value = 1; await load(); $q.notify({ type: 'positive', message: 'Pacote validado, armazenado de forma privada e publicado para compradores.' })
  } catch (error) { failure(error) } finally { busy.value = false }
}
async function remove(item) { $q.dialog({title:'Remover versão '+item.version+'?',message:'O arquivo desta versão será removido do armazenamento privado. O pacote publicado não pode ser removido.',cancel:true,persistent:true}).onOk(async()=>{busy.value=true;try{await api.delete('/admin/products/aitonotify/packages/'+item.id,{headers:headers()});await load()}catch(error){failure(error)}finally{busy.value=false}}) }
async function activate(item) { busy.value = true; try { await api.post(`/admin/products/aitonotify/packages/${item.id}/activate`, {}, { headers: headers() }); await load() } catch (error) { failure(error) } finally { busy.value = false } }
async function testDownload(item) { try { const data = (await api.post(`/admin/products/aitonotify/packages/${item.id}/ticket`, {}, { headers: headers() })).data.data; window.location.assign(data.url) } catch (error) { failure(error) } }
onMounted(load)
</script>
<template>
  <section class="package-manager">
    <header><q-icon name="mdi-package-variant-closed-check" size="30px"/><div><h3>Entrega privada do Desktop</h3><p>Publique uma versão sem adicionar arquivos pesados ao código do site.</p></div><q-btn flat round icon="mdi-refresh" aria-label="Atualizar pacotes" :disable="busy" @click="load"/></header>
    <div v-if="current" class="package-current"><q-icon name="mdi-check-decagram"/><div><strong>Versão {{current.version}} publicada · {{size(current.size)}}</strong><small>{{current.filename}}</small></div><q-btn outline no-caps label="Testar download" icon="mdi-download" @click="testDownload(current)"/></div>
    <p v-else class="package-note">Ainda não há pacote Desktop publicado. O botão do cliente será liberado após o primeiro envio.</p>
    <q-form @submit.prevent="publish"><q-tabs v-model="source" dense align="left" active-color="teal-3"><q-tab name="file" label="Enviar ZIP/RAR"/><q-tab name="drive" label="Importar do Google Drive"/></q-tabs><div class="package-fields"><q-input dark outlined v-model="form.version" label="Versão" maxlength="40" placeholder="1.0.0" :disable="busy"/><q-file v-if="source==='file'" dark outlined v-model="file" label="Pacote do instalador (.zip ou .rar)" accept=".zip,.rar" :max-file-size="1073741824" :disable="busy"/><template v-else><q-input dark outlined v-model.trim="form.url" label="Link público de um arquivo do Google Drive" :disable="busy"/><q-input dark outlined v-model.trim="form.filename" label="Nome original do arquivo (.zip ou .rar)" :disable="busy"/></template><q-input dark outlined v-model="form.notes" label="O que mudou nesta versão" type="textarea" autogrow maxlength="3000" :disable="busy" class="package-notes"/></div><q-linear-progress v-if="busy" rounded size="7px" color="teal-4" :value="progress" :indeterminate="source==='drive' || progress===1"/><div class="package-actions"><small>O servidor copia o arquivo para armazenamento privado. Após importar, você pode restringir o compartilhamento no Drive; a origem continuará pública enquanto essa permissão existir lá. O cliente recebe somente um download privado de uso único. Cada versão ocupa espaço no banco; remova as antigas quando não precisar mais delas.</small><q-btn unelevated color="teal-7" no-caps type="submit" label="Publicar versão Desktop" icon="mdi-cloud-upload-outline" :loading="busy"/></div></q-form>
    <q-expansion-item v-if="items.length" icon="mdi-history" label="Versões anteriores e teste de entrega"><div v-for="item in items" :key="item.id" class="package-history"><div><strong>{{item.version}} <q-badge v-if="item.active" color="teal" label="Atual"/></strong><small>{{item.filename}} · {{size(item.size)}}</small><p>{{item.notes}}</p><code>SHA-256 {{item.sha256}}</code></div><q-btn flat no-caps icon="mdi-download" label="Testar" @click="testDownload(item)"/><q-btn v-if="!item.active" outline no-caps label="Usar esta versão" :disable="busy" @click="activate(item)"/><q-btn v-if="!item.active" flat round color="red-3" icon="mdi-delete-outline" aria-label="Remover versão antiga" :disable="busy" @click="remove(item)"/></div></q-expansion-item>
    <div class="cloud-soon"><q-icon name="mdi-cloud-outline"/><span>Cloud / Render API</span><q-badge outline label="Em breve"/></div>
  </section>
</template>
<style scoped>
.package-manager{margin:24px 16px;padding:24px;border:1px solid #315e56;border-radius:16px;background:#061d20;color:#effffb}.package-manager header{display:flex;gap:13px;align-items:center}.package-manager header>div{flex:1;min-width:0}.package-manager h3{font-size:20px;line-height:1.4;margin:0}.package-manager p{font-size:12px;line-height:1.8;color:#adcfc4}.package-fields{display:grid;grid-template-columns:1fr 1fr;gap:17px;margin:20px 0}.package-notes{grid-column:1/-1}.package-current{display:flex;align-items:center;gap:12px;border:1px solid #4b9a7d;background:#174137;padding:16px;border-radius:13px;margin:20px 0}.package-current>div{flex:1;min-width:0}.package-current strong,.package-current small,.package-history small{display:block;overflow-wrap:anywhere}.package-current small{font-size:11px;color:#b3d8c9;margin-top:5px}.package-actions{display:flex;align-items:center;gap:18px;margin:20px 0}.package-actions small{flex:1;line-height:1.8;color:#9fbdaf}.package-history{display:flex;align-items:center;gap:10px;padding:15px 0;border-bottom:1px solid #31564c}.package-history>div{flex:1;min-width:0}.package-history small{color:#a8c8b9;font-size:11px;margin:8px 0}.package-history p{margin:8px 0}.package-history code{font-size:9px;overflow-wrap:anywhere;color:#9eb9ad}.cloud-soon{display:flex;align-items:center;gap:10px;padding-top:20px;color:#aac5bb}.package-manager :deep(.q-field__native),.package-manager :deep(.q-field__label){color:#d8eee3}.package-manager :deep(.q-field__control:before){border-color:#52766e}@media(max-width:700px){.package-manager{margin:16px 8px;padding:16px}.package-fields{grid-template-columns:1fr}.package-actions,.package-current,.package-history{flex-wrap:wrap}.package-actions>.q-btn{width:100%}.package-current>div{flex-basis:75%}.package-history>div{flex-basis:100%}.package-history>.q-btn{flex:1}.package-manager h3{font-size:18px}}
</style>
